import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Plyr, APITypes } from 'plyr-react';
import 'plyr-react/plyr.css';
import { 
  FiRewind, 
  FiFastForward, 
  FiVolume2, 
  FiVolumeX, 
  FiSliders
} from 'react-icons/fi';
import { FaPlay, FaPause, FaClosedCaptioning } from 'react-icons/fa';
import { cn } from '../../../Utils';

const plyrVideoSource = {
  type: 'video' as const,
  sources: [
    {
      src: 'BQu2m4LI084',
      provider: 'youtube' as const,
    },
  ],
};

const plyrOptions = {
  controls: [], // headless
  settings: [],
  youtube: {
    noCookie: true,
    rel: 0,
    showinfo: 0,
    iv_load_policy: 3,
    modestbranding: 1,
    cc_load_policy: 1 // Enable captions initialization on YouTube embed
  }
};

type SectionThreeProps = {}

export const SectionThree: React.FC<SectionThreeProps> = (props) => {
  const [plyrInstance, setPlyrInstance] = useState<any>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(1);
  const [isMuted, setIsMuted] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  
  // Custom Controls visibility
  const [showControls, setShowControls] = useState(true);
  const controlsTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  
  // Custom Settings visibility
  const [showSettings, setShowSettings] = useState(false);
  const [playbackRate, setPlaybackRate] = useState(1);
  const [hasCaptionsActive, setHasCaptionsActive] = useState(false);

  const playerRef = useRef<APITypes>(null);

  // Poll for the actual initialized Plyr instance
  useEffect(() => {
    const interval = setInterval(() => {
      const plyr = playerRef.current?.plyr;
      if (plyr && typeof plyr.on === 'function') {
        setPlyrInstance(plyr);
        clearInterval(interval);
      }
    }, 50);

    return () => clearInterval(interval);
  }, []);

  // Listen to Plyr state/events
  useEffect(() => {
    if (!plyrInstance) return;

    const handlePlay = () => setIsPlaying(true);
    const handlePause = () => setIsPlaying(false);
    const handleTimeUpdate = () => {
      setCurrentTime(plyrInstance.currentTime);
    };
    const handleDurationChange = () => {
      setDuration(plyrInstance.duration || 0);
    };
    const handleVolumeChange = () => {
      setVolume(plyrInstance.volume);
      setIsMuted(plyrInstance.muted);
    };
    const handleWaiting = () => setIsLoading(true);
    const handlePlaying = () => setIsLoading(false);

    plyrInstance.on('playing', handlePlay);
    plyrInstance.on('pause', handlePause);
    plyrInstance.on('timeupdate', handleTimeUpdate);
    plyrInstance.on('ready', handleDurationChange);
    plyrInstance.on('volumechange', handleVolumeChange);
    plyrInstance.on('waiting', handleWaiting);
    plyrInstance.on('playing', handlePlaying);

    // Sync initial states
    setIsPlaying(plyrInstance.playing);
    setCurrentTime(plyrInstance.currentTime);
    setDuration(plyrInstance.duration || 0);
    setVolume(plyrInstance.volume);
    setIsMuted(plyrInstance.muted);

    return () => {
      plyrInstance.off('playing', handlePlay);
      plyrInstance.off('pause', handlePause);
      plyrInstance.off('timeupdate', handleTimeUpdate);
      plyrInstance.off('ready', handleDurationChange);
      plyrInstance.off('volumechange', handleVolumeChange);
      plyrInstance.off('waiting', handleWaiting);
      plyrInstance.off('playing', handlePlaying);
    };
  }, [plyrInstance]);

  // Controls visibility timeout
  const resetControlsTimeout = useCallback(() => {
    setShowControls(true);
    if (controlsTimeoutRef.current) {
      clearTimeout(controlsTimeoutRef.current);
    }
    if (isPlaying) {
      controlsTimeoutRef.current = setTimeout(() => {
        setShowControls(false);
        setShowSettings(false);
      }, 3000);
    }
  }, [isPlaying]);

  useEffect(() => {
    resetControlsTimeout();
    return () => {
      if (controlsTimeoutRef.current) {
        clearTimeout(controlsTimeoutRef.current);
      }
    };
  }, [isPlaying, resetControlsTimeout]);

  const handleMouseMove = () => {
    resetControlsTimeout();
  };

  // Player Actions
  const handlePlayPause = () => {
    if (plyrInstance) {
      plyrInstance.togglePlay();
    }
  };

  const handleRewind = () => {
    if (plyrInstance) {
      plyrInstance.rewind(10);
    }
  };

  const handleForward = () => {
    if (plyrInstance) {
      plyrInstance.forward(10);
    }
  };

  const handleToggleMute = () => {
    if (plyrInstance) {
      plyrInstance.muted = !plyrInstance.muted;
    }
  };

  const handleVolumeMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
    e.stopPropagation();
    const track = e.currentTarget;
    const updateVolume = (clientY: number) => {
      const rect = track.getBoundingClientRect();
      const height = rect.height;
      const clickY = rect.bottom - clientY;
      const newVolume = Math.max(0, Math.min(1, clickY / height));
      if (plyrInstance) {
        plyrInstance.volume = newVolume;
        plyrInstance.muted = false;
      }
    };

    updateVolume(e.clientY);

    const handleMouseMoveEvent = (moveEvent: MouseEvent) => {
      updateVolume(moveEvent.clientY);
    };

    const handleMouseUpEvent = () => {
      document.removeEventListener('mousemove', handleMouseMoveEvent);
      document.removeEventListener('mouseup', handleMouseUpEvent);
    };

    document.addEventListener('mousemove', handleMouseMoveEvent);
    document.addEventListener('mouseup', handleMouseUpEvent);
  };

  const handleVolumeTouchStart = (e: React.TouchEvent<HTMLDivElement>) => {
    e.stopPropagation();
    const track = e.currentTarget;
    const updateVolume = (clientY: number) => {
      const rect = track.getBoundingClientRect();
      const height = rect.height;
      const clickY = rect.bottom - clientY;
      const newVolume = Math.max(0, Math.min(1, clickY / height));
      if (plyrInstance) {
        plyrInstance.volume = newVolume;
        plyrInstance.muted = false;
      }
    };

    updateVolume(e.touches[0].clientY);

    const handleTouchMoveEvent = (moveEvent: TouchEvent) => {
      updateVolume(moveEvent.touches[0].clientY);
    };

    const handleTouchEndEvent = () => {
      document.removeEventListener('touchmove', handleTouchMoveEvent);
      document.removeEventListener('touchend', handleTouchEndEvent);
    };

    document.addEventListener('touchmove', handleTouchMoveEvent);
    document.addEventListener('touchend', handleTouchEndEvent);
  };

  const handleProgressMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
    e.stopPropagation();
    const track = e.currentTarget;
    const seek = (clientX: number) => {
      const rect = track.getBoundingClientRect();
      const width = rect.width;
      const clickX = clientX - rect.left;
      const newPercentage = Math.max(0, Math.min(1, clickX / width));
      if (plyrInstance && duration) {
        plyrInstance.currentTime = newPercentage * duration;
      }
    };

    seek(e.clientX);

    const handleMouseMoveEvent = (moveEvent: MouseEvent) => {
      seek(moveEvent.clientX);
    };

    const handleMouseUpEvent = () => {
      document.removeEventListener('mousemove', handleMouseMoveEvent);
      document.removeEventListener('mouseup', handleMouseUpEvent);
    };

    document.addEventListener('mousemove', handleMouseMoveEvent);
    document.addEventListener('mouseup', handleMouseUpEvent);
  };

  const handleProgressTouchStart = (e: React.TouchEvent<HTMLDivElement>) => {
    e.stopPropagation();
    const track = e.currentTarget;
    const seek = (clientX: number) => {
      const rect = track.getBoundingClientRect();
      const width = rect.width;
      const clickX = clientX - rect.left;
      const newPercentage = Math.max(0, Math.min(1, clickX / width));
      if (plyrInstance && duration) {
        plyrInstance.currentTime = newPercentage * duration;
      }
    };

    seek(e.touches[0].clientX);

    const handleTouchMoveEvent = (moveEvent: TouchEvent) => {
      seek(moveEvent.touches[0].clientX);
    };

    const handleTouchEndEvent = () => {
      document.removeEventListener('touchmove', handleTouchMoveEvent);
      document.removeEventListener('touchend', handleTouchEndEvent);
    };

    document.addEventListener('touchmove', handleTouchMoveEvent);
    document.addEventListener('touchend', handleTouchEndEvent);
  };

  const handleSetSpeed = (rate: number) => {
    if (plyrInstance) {
      plyrInstance.speed = rate;
      setPlaybackRate(rate);
      setShowSettings(false);
    }
  };

  const handleToggleSettings = () => {
    setShowSettings(!showSettings);
  };

  const handleToggleCaptions = () => {
    if (plyrInstance) {
      try {
        plyrInstance.toggleCaptions();
        setHasCaptionsActive(plyrInstance.captions?.active || false);
      } catch (err) {
        // Fallback for YouTube embed API captions control
        const ytPlayer = plyrInstance.embed;
        if (ytPlayer && typeof ytPlayer.loadModule === 'function') {
          if (hasCaptionsActive) {
            ytPlayer.unloadModule('captions');
            setHasCaptionsActive(false);
          } else {
            ytPlayer.loadModule('captions');
            if (typeof ytPlayer.setOption === 'function') {
              ytPlayer.setOption('captions', 'track', { languageCode: 'en' });
            }
            setHasCaptionsActive(true);
          }
        } else {
          console.warn("Captions toggle is not supported by the embed player.");
          setHasCaptionsActive(!hasCaptionsActive);
        }
      }
    }
  };

  const formatTime = (timeInSeconds: number) => {
    if (isNaN(timeInSeconds)) return '00:00:00';
    const hours = Math.floor(timeInSeconds / 3600);
    const minutes = Math.floor((timeInSeconds % 3600) / 60);
    const seconds = Math.floor(timeInSeconds % 60);

    const pad = (num: number) => String(num).padStart(2, '0');
    return `${pad(hours)}:${pad(minutes)}:${pad(seconds)}`;
  };

  const handleOverlayClick = (e: React.MouseEvent) => {
    if (e.target === e.currentTarget) {
      handlePlayPause();
    }
  };

  return (
    <div className="bg-primary-500 p-6 md:p-12 flex items-center justify-center min-h-[500px]">
      
      {/* 3D Realistic Landscape iPhone Mockup */}
      <div className="relative w-full max-w-[850px] aspect-[19.5/9] rounded-[48px] p-[3px] iphone-outer-rim select-none overflow-visible">
        
        {/* Antenna Bands */}
        <div className="absolute top-0 left-[18%] w-[5px] h-[3px] iphone-antenna-band" />
        <div className="absolute bottom-0 left-[18%] w-[5px] h-[3px] iphone-antenna-band" />
        <div className="absolute top-0 right-[18%] w-[5px] h-[3px] iphone-antenna-band" />
        <div className="absolute bottom-0 right-[18%] w-[5px] h-[3px] iphone-antenna-band" />

        {/* Screen Bezel Container */}
        <div className="relative w-full h-full rounded-[45px] p-[10px] bg-black iphone-inner-bezel">
          
          {/* Screen Display */}
          <div 
            className="relative w-full h-full rounded-[34px] overflow-hidden bg-black iphone-screen-player group"
            onMouseMove={handleMouseMove}
            onMouseLeave={() => isPlaying && setShowControls(false)}
          >
            {/* Headless Plyr Video */}
            <Plyr ref={playerRef} source={plyrVideoSource} options={plyrOptions} />

            {/* Dynamic Island Notch (Left edge in Landscape mode) */}
            <div className="bg-black rounded-full z-30 shadow-[inset_0_1.5px_3px_rgba(0,0,0,0.95),0_0.5px_0.5px_rgba(255,255,255,0.15)] flex flex-col items-center justify-center iphone-dynamic-island">
              {/* Realistic Camera Lens */}
              <div className="bg-neutral-900 rounded-full border border-white/5 shadow-inner flex items-center justify-center relative overflow-hidden iphone-camera-lens">
                {/* Outer lens glass coating reflection */}
                <div className="absolute inset-0 bg-gradient-to-tr from-indigo-950 via-transparent to-purple-950 opacity-40" />
                {/* Deep aperture reflection */}
                <div className="bg-black rounded-full flex items-center justify-center relative iphone-camera-lens-aperture">
                  {/* Subtle purple-blue glass reflection */}
                  <div className="absolute top-[10%] left-[10%] bg-violet-600/40 rounded-full blur-[0.2px] iphone-camera-lens-reflection" />
                  {/* Tiny specular highlight */}
                  <div className="absolute top-[10%] right-[10%] bg-white/80 rounded-full iphone-camera-lens-highlight" />
                </div>
              </div>
              
              {/* Face ID / Proximity Sensor (Faint dark circle, matching real hardware) */}
              <div className="bg-neutral-950 rounded-full opacity-60 border border-white/5 shadow-[inset_0_0.5px_1px_rgba(0,0,0,0.8)] iphone-sensor" />
            </div>

            {/* Custom Interactive Controls Overlay */}
            <div 
              onClick={handleOverlayClick}
              className={cn(
                "absolute inset-0 bg-gradient-to-t from-black/50 via-transparent to-black/35 flex flex-col justify-between p-6 pl-18 pr-6 pb-6 transition-opacity duration-300 z-10 select-none cursor-pointer",
                showControls ? "opacity-100" : "opacity-0 pointer-events-none"
              )}
            >
              <div /> {/* Top spacing */}

              {/* Centered Player Controls */}
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex items-center justify-center gap-8 z-20">
                {/* 10s Rewind */}
                <button 
                  onClick={handleRewind}
                  className="text-white/80 hover:text-white transition-all duration-200 hover:scale-110 active:scale-95 focus:outline-none"
                  title="Rewind 10s"
                >
                  <FiRewind className="w-8 h-8" />
                </button>

                {/* Big Center Play/Pause (No circle background, matching picture) */}
                <button 
                  onClick={handlePlayPause}
                  className="text-white hover:text-white/90 transition-all duration-200 hover:scale-110 active:scale-95 focus:outline-none px-2"
                  title={isPlaying ? "Pause" : "Play"}
                >
                  {isPlaying ? (
                    <FaPause className="w-12 h-12 text-white" />
                  ) : (
                    <FaPlay className="w-12 h-12 text-white" />
                  )}
                </button>

                {/* 10s Fast Forward */}
                <button 
                  onClick={handleForward}
                  className="text-white/80 hover:text-white transition-all duration-200 hover:scale-110 active:scale-95 focus:outline-none"
                  title="Forward 10s"
                >
                  <FiFastForward className="w-8 h-8" />
                </button>
              </div>

              {/* Right Side Vertical Panel (Volume / Settings) - Floating directly, matching picture */}
              <div className="absolute right-6 top-1/2 -translate-y-1/2 flex flex-col items-center gap-5 z-20">
                {/* Volume Mute Toggle */}
                <button 
                  onClick={handleToggleMute}
                  className="text-white/80 hover:text-white transition-colors duration-200 focus:outline-none"
                  title={isMuted ? "Unmute" : "Mute"}
                >
                  {isMuted || volume === 0 ? <FiVolumeX className="w-5 h-5" /> : <FiVolume2 className="w-5 h-5" />}
                </button>
                
                {/* Custom Vertical Volume Slider (Sleeker design) */}
                <div 
                  onMouseDown={handleVolumeMouseDown}
                  onTouchStart={handleVolumeTouchStart}
                  className="w-4 h-18 bg-white/20 rounded-full relative cursor-pointer overflow-hidden touch-none"
                  title="Volume"
                >
                  <div 
                    className="absolute bottom-0 left-0 right-0 bg-white rounded-full transition-all duration-75"
                    style={{ height: `${isMuted ? 0 : volume * 100}%` }}
                  />
                </div>
                
                {/* Subtitles Button (CC Icon) */}
                <button 
                  onClick={handleToggleCaptions}
                  className={cn(
                    "text-white/80 hover:text-white transition-colors duration-200 focus:outline-none",
                    hasCaptionsActive ? "text-primary-300" : ""
                  )}
                  title="Toggle Captions"
                >
                  <FaClosedCaptioning className="w-5 h-5" />
                </button>
                
                {/* Settings / Tuning Button */}
                <div className="relative">
                  <button 
                    onClick={handleToggleSettings}
                    className={cn(
                      "text-white/80 hover:text-white transition-colors duration-200 focus:outline-none",
                      showSettings ? "text-primary-300" : ""
                    )}
                    title="Settings"
                  >
                    <FiSliders className="w-5 h-5" />
                  </button>

                  {/* Settings Speed Menu */}
                  {showSettings && (
                    <div className="absolute right-10 bottom-0 w-32 bg-slate-950/95 backdrop-blur-xl rounded-2xl p-2 border border-white/10 flex flex-col gap-1 text-white text-xs z-30 shadow-2xl animate-fade-in">
                      <div className="text-white/40 font-semibold px-2 py-1 border-b border-white/5 mb-1">Speed</div>
                      {[0.5, 1, 1.5, 2].map((rate) => (
                        <button 
                          key={rate} 
                          onClick={() => handleSetSpeed(rate)}
                          className={cn(
                            "w-full text-left px-2 py-1.5 rounded-lg hover:bg-white/10 transition-colors focus:outline-none",
                            playbackRate === rate ? "text-primary-300 font-semibold bg-white/5" : ""
                          )}
                        >
                          {rate === 1 ? 'Normal' : `${rate}x`}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              {/* Bottom Scrubber and Times - Floating directly on bottom, matching picture */}
              <div className="absolute bottom-6 left-12 right-12 flex items-center gap-4 z-20">
                {/* Current Time */}
                <span className="text-white/90 text-[11px] font-mono select-none tracking-wider">{formatTime(currentTime)}</span>
                
                {/* Scrubber Track */}
                <div 
                  onMouseDown={handleProgressMouseDown}
                  onTouchStart={handleProgressTouchStart}
                  className="flex-1 h-1.5 bg-white/20 rounded-full relative cursor-pointer overflow-hidden group/scrubber touch-none"
                >
                  {/* Scrubber Progress Fill */}
                  <div 
                    className="absolute left-0 top-0 bottom-0 bg-white rounded-full transition-all duration-75"
                    style={{ width: `${(currentTime / (duration || 1)) * 100}%` }}
                  />
                </div>
                
                {/* Total / Remaining Time */}
                <span className="text-white/90 text-[11px] font-mono select-none tracking-wider">{formatTime(duration)}</span>
              </div>
            </div>

            {/* Loading Spinner */}
            {isLoading && (
              <div className="absolute inset-0 flex items-center justify-center bg-black/40 pointer-events-none z-20">
                <div className="w-12 h-12 border-4 border-white/20 border-t-white rounded-full animate-spin" />
              </div>
            )}
          </div>
        </div>

        {/* Realistic Hardware Side Buttons (Rotated: Top and Bottom edges) */}
        {/* Top Edge Button (Right side if vertical: Power Button) */}
        <div className="absolute top-[-5px] left-[26%] w-[96px] h-[5px] rounded-t-[3px] iphone-button-top iphone-button-shadow" />

        {/* Bottom Edge Buttons (Left side if vertical: Action Button, Volume Up, Volume Down) */}
        {/* Action Button */}
        <div className="absolute bottom-[-5px] left-[15%] w-[32px] h-[5px] rounded-b-[3px] iphone-button-bottom iphone-button-shadow" />
        {/* Volume Up */}
        <div className="absolute bottom-[-5px] left-[24%] w-[64px] h-[5px] rounded-b-[3px] iphone-button-bottom iphone-button-shadow" />
        {/* Volume Down */}
        <div className="absolute bottom-[-5px] left-[34%] w-[64px] h-[5px] rounded-b-[3px] iphone-button-bottom iphone-button-shadow" />
      </div>
    </div>
  );
};
